/**
 * Rótulos e listas do CRM (MASTER 012).
 *
 * O banco guarda apenas códigos; toda tradução para português do Brasil vive
 * aqui, seguindo o mesmo padrão de `lib/finance/constants.ts` e
 * `lib/inventory/constants.ts`.
 */

export const LEAD_STATUS: Record<string, string> = {
  NEW: "Novo",
  CONTACT_ATTEMPTED: "Contato tentado",
  CONTACTED: "Contatado",
  QUALIFIED: "Qualificado",
  UNQUALIFIED: "Desqualificado",
  CONVERTED: "Convertido",
  ARCHIVED: "Arquivado",
};

/** Etapas em que o lead ainda pode ser qualificado e convertido. */
export const LEAD_ELIGIBLE_STATUS = ["NEW", "CONTACT_ATTEMPTED", "CONTACTED", "QUALIFIED"] as const;

export const OPPORTUNITY_STATUS: Record<string, string> = {
  OPEN: "Em aberto",
  WON: "Ganha",
  LOST: "Perdida",
  CANCELED: "Cancelada",
};

/** Apenas oportunidades em aberto entram no pipeline e na previsão. */
export const OPEN_OPPORTUNITY_STATUS = ["OPEN"] as const;

export const QUOTE_STATUS: Record<string, string> = {
  DRAFT: "Rascunho",
  PENDING_APPROVAL: "Aguardando aprovação",
  APPROVED: "Aprovada",
  SENT: "Enviada",
  ACCEPTED: "Aceita",
  REJECTED: "Rejeitada",
  EXPIRED: "Vencida",
  CANCELED: "Cancelada",
};

/** Transições que o servidor aceita; qualquer outra é recusada. */
export const QUOTE_FLOW: Record<string, string[]> = {
  DRAFT: ["PENDING_APPROVAL"],
  PENDING_APPROVAL: ["APPROVED"],
  APPROVED: ["SENT"],
  SENT: ["ACCEPTED", "REJECTED"],
};

export const ACTIVITY_TYPE: Record<string, string> = {
  CALL: "Ligação",
  MEETING: "Reunião",
  EMAIL: "E-mail",
  WHATSAPP: "WhatsApp",
  VISIT: "Visita",
  TASK: "Tarefa",
  FOLLOW_UP: "Retomada",
  NOTE: "Anotação",
  OTHER: "Outra",
};

export const ACTIVITY_STATUS: Record<string, string> = {
  PENDING: "Pendente",
  COMPLETED: "Concluída",
  CANCELED: "Cancelada",
};

export const COMMERCIAL_STATUS: Record<string, string> = {
  ACTIVE: "Ativo",
  INACTIVE: "Inativo",
  BLOCKED: "Bloqueado",
};

export const REPRESENTATIVE_TYPE: Record<string, string> = {
  INTERNAL: "Funcionário interno",
  EXTERNAL: "Representante externo",
  COMPANY: "Empresa de representação",
};

export const REASON_KIND: Record<string, string> = {
  LEAD: "Desqualificação de lead",
  LOSS: "Perda de oportunidade",
};

export const COMMISSION_TRIGGER: Record<string, string> = {
  SALE_CONFIRMED: "Venda confirmada (MASTER 013)",
  RECEIPT_CONFIRMED: "Recebimento confirmado (MASTER 013)",
};

export const COMMISSION_RATE_TYPE: Record<string, string> = {
  PERCENT: "Percentual sobre o valor",
  FIXED_PER_UNIT: "Valor fixo por unidade",
};

export const CHANNEL_TYPE: Record<string, string> = {
  PHONE: "Telefone",
  EMAIL: "E-mail",
  WHATSAPP: "WhatsApp",
  PREFERRED: "Canal preferido do contato",
};

export const leadStatusLabel = (status: string | null | undefined) =>
  status ? (LEAD_STATUS[status] ?? status) : "—";

export const opportunityStatusLabel = (status: string | null | undefined) =>
  status ? (OPPORTUNITY_STATUS[status] ?? status) : "—";

export const quoteStatusLabel = (status: string | null | undefined) =>
  status ? (QUOTE_STATUS[status] ?? status) : "—";

export const activityTypeLabel = (type: string | null | undefined) =>
  type ? (ACTIVITY_TYPE[type] ?? type) : "—";

export const activityStatusLabel = (status: string | null | undefined) =>
  status ? (ACTIVITY_STATUS[status] ?? status) : "—";

export const commercialStatusLabel = (status: string | null | undefined) =>
  status ? (COMMERCIAL_STATUS[status] ?? status) : "—";

export const representativeTypeLabel = (type: string | null | undefined) =>
  type ? (REPRESENTATIVE_TYPE[type] ?? type) : "—";

/** Kinds aceitos por `crm_query` para listagem tabular. */
export const CRM_LIST_KINDS = [
  "customers",
  "companies",
  "contacts",
  "leads",
  "opportunities",
  "opportunity_items",
  "stage_history",
  "quotes",
  "quote_items",
  "approvals",
  "activities",
  "activity_history",
  "representatives",
  "portfolios",
  "segments",
  "sources",
  "reasons",
  "tags",
  "customer_tags",
  "territories",
  "payment_terms",
  "pipelines",
  "stages",
  "authorities",
  "commission_plans",
  "commission_rules",
  "variants",
  "price_tables",
  "merge_requests",
] as const;

/**
 * Chaves de filtro aceitas por `crm_query`. O servidor só aplica filtros desta
 * lista branca; qualquer outra chave é ignorada, então a tela deve respeitar
 * este conjunto para não prometer um filtro que não acontece.
 */
export const CRM_FILTER_KEYS = [
  "id",
  "company_id",
  "status",
  "representative_id",
  "commercial_segment_id",
  "acquisition_source_id",
  "opportunity_id",
  "quote_id",
  "pipeline_id",
  "activity_id",
  "assigned_user_id",
  "q",
  "from",
  "to",
] as const;

/** Colunas numéricas de oportunidade/proposta, para alinhar na tabela. */
export const CURRENCY = "BRL" as const;

/**
 * Configuração declarativa das áreas do CRM (MASTER 012).
 *
 * Cada área descreve o `kind` lido por `crm_query`, o `kind` gravado por
 * `crm_save`, as permissões de leitura/escrita e os campos do formulário. As
 * telas são geradas a partir daqui, então adicionar um campo comercial é uma
 * alteração de dados — não de markup.
 *
 * Segmentos, origens, motivos, etiquetas, territórios, condições de pagamento,
 * pipelines, etapas, alçadas e planos de comissão ficam em `configurations`
 * porque são cadastros da própria organização, nunca dados de uma empresa.
 */

export type FieldType =
  | "text"
  | "email"
  | "number"
  | "date"
  | "datetime-local"
  | "options"
  | "lookup"
  | "longtext";

export type Field = {
  key: string;
  label: string;
  type?: FieldType;
  /** Opções fixas quando `type === "options"`. */
  options?: string[];
  /** `kind` consultado em `crm_query` quando `type === "lookup"`. */
  lookup?: string;
  required?: boolean;
  /** Campo carregado junto para o formulário (ex.: nome da empresa escolhida). */
  hint?: string;
};

export type Area = {
  title: string;
  /** `kind` enviado para `crm_query`. */
  query: string;
  /** `kind` enviado para `crm_save`; ausente quando o cadastro é só leitura. */
  save?: string;
  permission: string;
  /** Permissão necessária para gravar; o servidor exige a mesma chave. */
  write?: string;
  fields: Field[];
  /** Colunas exibidas na listagem, na ordem desejada. */
  columns: string[];
  /** `kind` de `crm_query` usado como options em filtros. */
  filters?: { key: string; label: string; kind: string; permission: string }[];
};

const field = (key: string, label: string, extra: Partial<Field> = {}): Field => ({
  key,
  label,
  ...extra,
});

const companyField = field("company_id", "Empresa", {
  lookup: "companies",
  required: true,
  hint: "legal_name",
});
const nameField = field("name", "Nome", { required: true });

/** Áreas operacionais do funil comercial. */
export const areas: Record<string, Area> = {
  leads: {
    title: "Leads",
    query: "leads",
    save: "lead",
    permission: "leads.read",
    write: "leads.create",
    fields: [
      nameField,
      field("company_name", "Empresa informada"),
      field("email", "E-mail", { type: "email" }),
      field("phone", "Telefone"),
      field("acquisition_source_id", "Origem", { lookup: "sources" }),
      field("commercial_segment_id", "Segmento", { lookup: "segments" }),
      field("status", "Status", {
        type: "options",
        options: ["NEW", "CONTACT_ATTEMPTED", "CONTACTED", "QUALIFIED", "UNQUALIFIED", "ARCHIVED"],
      }),
      field("disqualification_reason_id", "Motivo de desqualificação", { lookup: "reasons" }),
      field("processing_purpose", "Finalidade do tratamento", { type: "longtext" }),
      field("notes", "Observações", { type: "longtext" }),
    ],
    columns: ["name", "company_name", "email", "status", "created_at"],
    filters: [
      { key: "status", label: "Status", kind: "", permission: "leads.read" },
      { key: "acquisition_source_id", label: "Origem", kind: "sources", permission: "crm.read" },
      { key: "assigned_user_id", label: "Responsável", kind: "", permission: "leads.read" },
    ],
  },
  clientes: {
    title: "Clientes",
    query: "customers",
    save: "customer",
    permission: "customers.read",
    write: "customers.create",
    fields: [
      companyField,
      field("customer_code", "Código comercial"),
      field("customer_type", "Tipo"),
      field("commercial_status", "Status comercial", {
        type: "options",
        options: ["ACTIVE", "INACTIVE", "BLOCKED"],
      }),
      field("commercial_segment_id", "Segmento", { lookup: "segments" }),
      field("acquisition_source_id", "Origem", { lookup: "sources" }),
      field("price_table_id", "Tabela de preços", { lookup: "price_tables" }),
      field("payment_terms_id", "Condição de pagamento", { lookup: "payment_terms" }),
      field("notes", "Observações comerciais", { type: "longtext" }),
    ],
    columns: ["customer_code", "company_id", "commercial_status", "commercial_segment_id"],
    filters: [
      { key: "status", label: "Status", kind: "", permission: "customers.read" },
      {
        key: "commercial_segment_id",
        label: "Segmento",
        kind: "segments",
        permission: "crm.read",
      },
      { key: "acquisition_source_id", label: "Origem", kind: "sources", permission: "crm.read" },
    ],
  },
  oportunidades: {
    title: "Oportunidades",
    query: "opportunities",
    save: "opportunity",
    permission: "opportunities.read",
    write: "opportunities.create",
    fields: [
      companyField,
      field("title", "Título", { required: true }),
      field("stage_id", "Etapa", { lookup: "stages", required: true }),
      field("primary_contact_id", "Contato principal", { lookup: "contacts" }),
      field("expected_close_date", "Previsão de fechamento", { type: "date" }),
      field("description", "Descrição", { type: "longtext" }),
    ],
    columns: [
      "title",
      "company_id",
      "representative_id",
      "estimated_value",
      "probability",
      "status",
      "expected_close_date",
    ],
    filters: [
      { key: "status", label: "Status", kind: "", permission: "opportunities.read" },
      {
        key: "representative_id",
        label: "Representante",
        kind: "representatives",
        permission: "representatives.read",
      },
    ],
  },
  propostas: {
    title: "Propostas",
    query: "quotes",
    permission: "quotes.read",
    write: "quotes.create",
    fields: [
      companyField,
      field("price_table_id", "Tabela de preços vigente", {
        lookup: "price_tables",
        required: true,
      }),
      field("primary_contact_id", "Contato", { lookup: "contacts" }),
      field("opportunity_id", "Oportunidade", { lookup: "opportunities" }),
      field("valid_until", "Validade", { type: "date", required: true }),
      field("discount_percent", "Desconto %", { type: "number" }),
      field("freight", "Frete estimado (R$)", { type: "number" }),
      field("tax_amount", "Tributos informados (R$)", { type: "number" }),
      field("notes", "Observações", { type: "longtext" }),
    ],
    columns: ["quote_number", "version", "company_id", "total", "status", "valid_until"],
    filters: [
      { key: "status", label: "Status", kind: "", permission: "quotes.read" },
      {
        key: "representative_id",
        label: "Representante",
        kind: "representatives",
        permission: "representatives.read",
      },
    ],
  },
  atividades: {
    title: "Atividades",
    query: "activities",
    save: "activity",
    permission: "activities.read",
    write: "activities.manage",
    fields: [
      field("company_id", "Empresa", { lookup: "companies" }),
      field("lead_id", "Lead", { lookup: "leads" }),
      field("opportunity_id", "Oportunidade", { lookup: "opportunities" }),
      field("subject", "Assunto", { required: true }),
      field("activity_type", "Tipo", {
        type: "options",
        options: [
          "CALL",
          "MEETING",
          "EMAIL",
          "WHATSAPP",
          "VISIT",
          "TASK",
          "FOLLOW_UP",
          "NOTE",
          "OTHER",
        ],
        required: true,
      }),
      field("scheduled_at", "Agendamento", { type: "datetime-local", required: true }),
      field("description", "Descrição", { type: "longtext" }),
      field("status", "Status", { type: "options", options: ["PENDING", "COMPLETED", "CANCELED"] }),
      field("outcome", "Resultado", { type: "longtext" }),
      field("reason", "Motivo da alteração", { type: "longtext" }),
    ],
    columns: ["subject", "activity_type", "company_id", "scheduled_at", "status"],
    filters: [
      { key: "status", label: "Status", kind: "", permission: "activities.read" },
      { key: "assigned_user_id", label: "Responsável", kind: "", permission: "activities.read" },
    ],
  },
  representantes: {
    title: "Representantes",
    query: "representatives",
    save: "representative",
    permission: "representatives.read",
    write: "representatives.manage",
    fields: [
      nameField,
      field("representative_code", "Código", { required: true }),
      field("representative_type", "Tipo", {
        type: "options",
        options: ["INTERNAL", "EXTERNAL", "COMPANY"],
        required: true,
      }),
      field("company_id", "Empresa de representação", { lookup: "companies" }),
      field("user_id", "Usuário vinculado (opcional)", { lookup: "members" }),
      field("assigned_manager_id", "Gestor responsável", { lookup: "members" }),
      field("status", "Status", { type: "options", options: ["ACTIVE", "INACTIVE"] }),
    ],
    columns: ["name", "representative_code", "representative_type", "status"],
  },
  carteiras: {
    title: "Carteiras",
    query: "portfolios",
    permission: "customers.read",
    write: "portfolios.manage",
    fields: [
      field("company_id", "Cliente", { lookup: "companies", required: true }),
      field("representative_id", "Representante", {
        lookup: "representatives",
        required: true,
      }),
      field("reason", "Motivo da atribuição", { required: true }),
    ],
    columns: ["company_id", "representative_id", "started_at", "ended_at"],
  },
};

/** Cadastros da própria organização, configuráveis por `crm.configure`. */
export const configurations: Record<string, Area> = {
  segmentos: {
    title: "Segmentos",
    query: "segments",
    save: "segment",
    permission: "crm.read",
    write: "crm.configure",
    fields: [nameField, field("status", "Status", { type: "options", options: ["ACTIVE", "INACTIVE"] })],
    columns: ["name", "status"],
  },
  origens: {
    title: "Origens",
    query: "sources",
    save: "source",
    permission: "crm.read",
    write: "crm.configure",
    fields: [nameField, field("status", "Status", { type: "options", options: ["ACTIVE", "INACTIVE"] })],
    columns: ["name", "status"],
  },
  motivos: {
    title: "Motivos",
    query: "reasons",
    save: "reason",
    permission: "crm.read",
    write: "crm.configure",
    fields: [
      nameField,
      field("kind", "Finalidade", { type: "options", options: ["LEAD", "LOSS"], required: true }),
    ],
    columns: ["name", "kind"],
  },
  etiquetas: {
    title: "Etiquetas",
    query: "tags",
    save: "tag",
    permission: "customers.read",
    write: "crm.configure",
    fields: [nameField],
    columns: ["name"],
  },
  territorios: {
    title: "Territórios",
    query: "territories",
    save: "territory",
    permission: "representatives.read",
    write: "crm.configure",
    fields: [
      nameField,
      field("region", "Região"),
      field("state", "UF"),
      field("city", "Cidade"),
      field("segment_id", "Segmento", { lookup: "segments" }),
    ],
    columns: ["name", "region", "state", "city"],
  },
  condicoes: {
    title: "Condições de pagamento",
    query: "payment_terms",
    save: "payment_terms",
    permission: "crm.read",
    write: "crm.configure",
    fields: [
      nameField,
      field("description", "Condições acordadas", { required: true }),
      field("status", "Status", { type: "options", options: ["ACTIVE", "INACTIVE"] }),
    ],
    columns: ["name", "description", "status"],
  },
  pipelines: {
    title: "Pipelines",
    query: "pipelines",
    save: "pipeline",
    permission: "opportunities.read",
    write: "crm.configure",
    fields: [nameField, field("status", "Status", { type: "options", options: ["ACTIVE", "INACTIVE"] })],
    columns: ["name", "status"],
  },
  etapas: {
    title: "Etapas",
    query: "stages",
    save: "stage",
    permission: "opportunities.read",
    write: "crm.configure",
    fields: [
      nameField,
      field("pipeline_id", "Pipeline", { lookup: "pipelines", required: true }),
      field("position", "Ordem", { type: "number", required: true }),
